/**
 * Reduce a constituency name to a stable lookup key.
 * Mirrors backend/src/config/constituencyNormalizer.js — strips (SC)/(ST)
 * reservation markers only, so "Nizamabad (Urban)" and "Nizamabad (Rural)"
 * stay distinct seats instead of collapsing onto one key.
 */
export const normalizeConstituencyKey = (name) =>
  String(name || '')
    .toLowerCase()
    .replace(/\((\s*(sc|st|gen|general)\s*)\)/gi, ' ')
    .replace(/[^a-z0-9]/g, '')
    .trim();

export const MLA_BY_KEY = TG_MLAS.reduce((acc, m) => {
  acc[m.key] = m;
  return acc;
}, {});

export const getMlaByConstituency = (name) =>
  MLA_BY_KEY[normalizeConstituencyKey(name)] || null;

export const getMlasByDistrict = (districtKey) =>
  TG_MLAS.filter((m) => m.districtKey === districtKey);

export default TG_MLAS;
